namespace Sunplus.Agent.Model.BL.Casino
{
    using Sunplus.Agent.Model.DL.Casino;
    using Sunplus.Libraries.APILogger;
    using System.Xml;
    using System.Text.RegularExpressions;
    using Fanex.Common;

    public class CasinoAPILogger : IAPILogger
    {
        private byte asSystemId = 2;
        private GetUserId asUserId;

        public CasinoAPILogger(byte systemId, GetUserId userId)
        {
            this.asSystemId = systemId;
            this.asUserId = userId;
        }

        public delegate int GetUserId();

        #region IAPILogger Members

        public void Write(int actionId, string functionName, string trackingValue, string returnValue, int returnCode)
        {
            int userId = this.asUserId();
            var custId = 0;
            if (!string.IsNullOrEmpty(trackingValue))
            {
                var pattern = @"(<[\w]+BCCustID>)([0-9]+)(</[\w]+BCCustID>)";
                Match regexMatch = Regex.Match(trackingValue, pattern, RegexOptions.IgnoreCase);                
                if (regexMatch.Success)
                {
                    custId = Converter.ToInt(regexMatch.Groups[2]);
                }
            }

            new CasinoDAO().WriteLog_UserLog_CasinoAPI(this.asSystemId, userId, custId, actionId, functionName, trackingValue, returnValue, returnCode);
        }

        #endregion
    }
}
